UPDATE users
SET USERNAME = #{username}, PASSWORD = #{password}, EMAIL = #{email}, ROLE = #{role},
    LAST_LOGIN_TIME = #{lastLoginTime,jdbcType=TIMESTAMP}, PASSWORD_CHANGE_TIME = #{passwordChangeTime,jdbcType=TIMESTAMP},
    FAILED_LOGIN_ATTEMPTS = #{failedLoginAttempts,jdbcType=INTEGER}, LOCK_TIME = #{lockTime,jdbcType=TIMESTAMP},
    PASSWORD_HISTORY = #{passwordHistory,jdbcType=VARCHAR}
WHERE USERID = #{userId}

UPDATE users
SET LAST_LOGIN_TIME = #{lastLoginTime}
WHERE USERID = #{userId}

UPDATE users
SET FAILED_LOGIN_ATTEMPTS = #{failedLoginAttempts}
WHERE USERID = #{userId}
